message = "MEET AT 5"
key = 3

secret = ""
for ch in message:
    if "A" <= ch <= "Z":
        secret += chr((ord(ch) - ord("A") + key) % 26 + ord("A"))
    else:
        secret += ch
print("Encrypted:", secret)

plain = ""
for ch in secret:
    if "A" <= ch <= "Z":
        plain += chr((ord(ch) - ord("A") - key) % 26 + ord("A"))
    else:
        plain += ch
print("Decrypted:", plain)
